/* src/components/Icon/Icon.module.css */
.Icon_icon {
  &.Icon_inline {
    display: inline-block;
  }
  &.Icon_block {
    display: block;
  }
  * {
    transform: rotate(0deg);
  }
}
:root[theme=dark] .Icon_keepColorsForDarkMode {
  --vWhite: var(--vAlwaysWhite);
  --vInk: var(--vInkAlwaysDark);
}
.Icon_default {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  line-height: 16px;
  &.Icon_filled,
  &.Icon_invertedFill {
    width: calc(16px + 16px);
    height: calc(16px + 16px);
    line-height: calc(16px + 16px);
    &.Icon_fillSize-large {
      width: calc(16px + 20px);
      height: calc(16px + 20px);
      line-height: calc(16px + 20px);
    }
    &.Icon_fillSize-extraLarge {
      width: calc(16px + 24px);
      height: calc(16px + 24px);
      line-height: calc(16px + 24px);
    }
  }
  .Icon_icon {
    width: 16px;
    height: 16px;
    line-height: 16px;
  }
  svg {
    width: 16px;
    height: 16px;
  }
}
.Icon_tiny {
  width: 8px;
  height: 8px;
  flex-shrink: 0;
  line-height: 8px;
  &.Icon_filled,
  &.Icon_invertedFill {
    width: calc(8px + 16px);
    height: calc(8px + 16px);
    line-height: calc(8px + 16px);
    &.Icon_fillSize-large {
      width: calc(8px + 20px);
      height: calc(8px + 20px);
      line-height: calc(8px + 20px);
    }
    &.Icon_fillSize-extraLarge {
      width: calc(8px + 24px);
      height: calc(8px + 24px);
      line-height: calc(8px + 24px);
    }
  }
  .Icon_icon {
    width: 8px;
    height: 8px;
    line-height: 6px;
  }
  svg {
    width: 8px;
    height: 8px;
  }
}
.Icon_small {
