}
.Icon_icon-wrapper {
  position: relative;
  &.Icon_inline {
    .Icon_icon {
      display: inline-block;
    }
    &.Icon_filled,
    &.Icon_invertedFill {
      display: inline-flex;
    }
  }
  &.Icon_block {
    .Icon_icon {
      display: block;
    }
    &.Icon_filled,
    &.Icon_invertedFill {
      display: flex;
    }
  }
  &.Icon_filled,
  &.Icon_invertedFill {
    border-radius: 50%;
    justify-content: center;
    text-align: center;
    align-items: center;
  }
  &.Icon_filled {
    &.Icon_wrapper-default,
    &.Icon_wrapper-black {
      background: var(--vInk);
    }
    &.Icon_wrapper-light-gray {
      background: var(--vUiHueDark);
    }
    &.Icon_wrapper-gray {
      background: var(--vInkLightest);
    }
    &.Icon_wrapper-blue {
      background: var(--vBlue);
    }
    &.Icon_wrapper-violet {
      background: var(--vViolet);
    }
    &.Icon_wrapper-dark-violet {
      background: var(--vVioletDark);
    }
    &.Icon_wrapper-dark-pink {
      background: var(--vPinkDark);
    }
    &.Icon_wrapper-red {
      background: var(--vRed);
    }
    &.Icon_wrapper-orange {
      background: var(--vOrange);
    }
    &.Icon_wrapper-dark-orange {
      background: var(--vOrangeDark);
    }
    &.Icon_wrapper-yellow {
      background: var(--vYellow);
    }
    &.Icon_wrapper-green {
      background: var(--vGreen);
    }
    &.Icon_wrapper-teal {
      background: var(--vTeal);
    }
    &.Icon_wrapper-white {
      background: var(--vWhite);
    }
    &.Icon_wrapper-bluebonnet {
      background: var(--vBluebonnet);
    }
    &.Icon_wrapper-dark-green {
      background: var(--vGreenDark);
    }
  }
  &.Icon_invertedFill {
    background: var(--vWhite);
    border: 1px solid;
    &.Icon_wrapper-default,
    &.Icon_wrapper-black {
      border-color: var(--vInk);
    }
    &.Icon_wrapper-light-gray {
      border-color: var(--vUiHueDark);
    }
    &.Icon_wrapper-gray {
      border-color: var(--vInkLightest);
    }
    &.Icon_wrapper-blue {
      border-color: var(--vBlue);
    }
    &.Icon_wrapper-violet {
      border-color: var(--vViolet);
    }
    &.Icon_wrapper-dark-violet {
      border-color: var(--vVioletDark);
    }
    &.Icon_wrapper-dark-pink {
      border-color: var(--vPinkDark);
    }
    &.Icon_wrapper-red {
      border-color: var(--vRed);
    }
    &.Icon_wrapper-orange {
      border-color: var(--vOrange);
    }
    &.Icon_wrapper-dark-orange {
      border-color: var(--vOrangeDark);
    }
    &.Icon_wrapper-yellow {
      border-color: var(--vYellow);
    }
    &.Icon_wrapper-green {
      border-color: var(--vGreen);
    }
    &.Icon_wrapper-teal {
      border-color: var(--vTeal);
    }
    &.Icon_wrapper-white {
      border-color: var(--vWhite);
    }
    &.Icon_wrapper-bluebonnet {
      border-color: var(--vBluebonnet);
    }
    &.Icon_wrapper-dark-green {
      border-color: var(--vGreenDark);
    }
  }
  .Icon_badge {
    font-size: 12px;
    position: absolute;
    bottom: -12px;
    right: -8px;
    background: var(--vOrange);
    color: var(--vWhite);
    font-weight: 600;
    padding: 4px;
    height: 24px;
    min-width: 24px;
    border-radius: 24px;
    border: 2px solid var(--vWhite);
    .Icon_badge-container {
      display: flex;
      align-items: center;
      justify-content: center;
      flex-direction: column;
      height: 12px;
      line-height: 13px;
      .Icon_badge-text {
        text-overflow: ellipsis;
        overflow: hidden;
        white-space: nowrap;
        max-width: 50px;
      }
    }
  }
}
