/* src/components/Tooltip/Tooltip.module.css */
@keyframes Tooltip_fadeInOut {
  from {
    visibility: visible;
    opacity: 0;
  }
  to {
    visibility: visible;
    opacity: 1;
  }
}
.Tooltip_tooltip-caption + .Tooltip_tooltip-title,
.Tooltip_tooltip-title + .Tooltip_tooltip-content {
  margin-top: 4px;
}
.Tooltip_tooltip-title {
  font-weight: 600;
  overflow-wrap: break-word;
  & + .Tooltip_tooltip-content {
    margin-top: 3px;
  }
}
.Tooltip_tooltip-content {
  font-weight: 400;
  overflow-wrap: break-word;
}
.Tooltip_tooltip {
  text-align: center;
  font-size: 12px !important;
  line-height: 14px !important;
  z-index: var(--vTooltip);
  background: var(--vInkAlwaysDark) !important;
  max-width: 320px;
  padding: 7px !important;
  border-radius: 2px !important;
  visibility: hidden;
}
.Tooltip_isOpen {
  animation-name: Tooltip_fadeInOut;
  animation-delay: 250ms;
  animation-duration: 250ms;
  animation-iteration-count: 1;
  animation-fill-mode: forwards;
}
:root[theme=dark] {
  .Tooltip_tooltip {
    border: 1px solid var(--vUiHue);
    [class*=react-tooltip-arrow] {
      border-right: 1px solid var(--vUiHue);
      border-bottom: 1px solid var(--vUiHue);
    }
  }
}

/* src/components/ActionList/ActionList.module.css */
.ActionList_wrapper {
  font-size: 14px;
  background-color: var(--vWhite);
  &.ActionList_appearance-condensed {
    font-size: 12px;
  }
  &.ActionList_fullHeight {
    height: 100%;
  }
  .ActionList_noItems {
    font-size: 14px;
    background-color: var(--vWhite);
    display: flex;
    height: 100%;
    justify-content: center;
    align-items: center;
    color: var(--vInkLighter);
    font-weight: 600;
    overflow-wrap: break-word;
    word-wrap: break-word;
    word-break: break-all;
    overflow: hidden;
    margin: 32px;
  }
  .ActionList_noItemsAdvanced {
    font-size: 14px;
    background-color: var(--vWhite);
    display: flex;
    flex-direction: column;
    margin: 32px;
    height: 100%;
    padding: 16px;
    justify-content: center;
    align-items: center;
    color: var(--vInkLighter);
    overflow-wrap: break-word;
    word-wrap: break-word;
    word-break: break-all;
    overflow: hidden;
    .ActionList_noItems-title {
      font-weight: 600;
      margin: 4px 0;
    }
    .ActionList_noItems-info {
      font-weight: 400;
      margin: 4px 0;
    }
  }
  .ActionList_group:not(:first-child) {
    border-top: 1px solid var(--vUiHue);
    margin-top: 8px;
  }
  .ActionList_groupName {
    color: var(--vInkLighter);
    text-transform: uppercase;
    font-weight: 600;
    font-size: 12px;
    padding: 8px;
  }
  .ActionList_items {
    list-style-type: none;
    margin: 0;
    padding: 0;
    &.ActionList_increasePadding {
      padding-top: 8px;
    }
  }
  &:not(:hover) .ActionList_item.ActionList_hoverStyle-default.ActionList_active,
  .ActionList_item.ActionList_hoverStyle-calendar.ActionList_active {
    cursor: pointer;
    background: var(--vBlue);
    :is(path, polygon, circle, rect):not(.ActionList_favorite *) {
      fill: var(--vWhite);
    }
    .ActionList_new-badge {
      background: var(--vWhite);
      color: var(--vBlue);
    }
    .ActionList_link {
      color: var(--vWhite);
    }
    .ActionList_caption {
      color: var(--vWhite);
    }
  }
  .ActionList_item {
    &:not(:hover) .ActionList_favorite .ActionList_favorite-not-selected {
      display: none;
    }
    &.ActionList_hoverStyle-default:hover {
      cursor: pointer;
      background: var(--vBlue);
      :is(path, polygon, circle, rect):not(.ActionList_favorite *) {
        fill: var(--vWhite);
      }
      .ActionList_new-badge {
        background: var(--vWhite);
        color: var(--vBlue);
      }
      .ActionList_link {
        color: var(--vWhite);
      }
      .ActionList_caption {
        color: var(--vWhite);
      }
    }
    &.ActionList_hoverStyle-calendar:hover:not(.ActionList_active) {
      cursor: pointer;
      background: var(--vUiHueLight);
    }
    &.ActionList_simple {
      &:hover:not(.ActionList_hoverStyle-calendar) .ActionList_link {
        color: var(--vWhite);
      }
      .ActionList_link {
        color: var(--vBlue);
      }
    }
    &.ActionList_disabled {
      .ActionList_link {
        color: var(--vInkLightest);
        cursor: not-allowed;
        &:hover {
          background-color: var(--vWhite);
          &.ActionList_link {
            color: var(--vInkLightest);
          }
        }
        .ActionList_caption {
          color: var(--vInkLightest);
        }
        :is(path, polygon, circle, rect):not(.ActionList_favorite *) {
          fill: var(--vInkLighter);
        }
      }
    }
    a {
      display: flex;
      padding: 8px;
      color: var(--vInk);
      text-align: left;
      text-decoration: none;
      font-weight: 600;
      overflow: hidden;
      align-items: center;
      &.ActionList_center {
        justify-content: center;
      }
    }
    span {
      margin-right: 8px;
    }
  }
  .ActionList_new-badge {
    border-radius: 16px;
    display: inline-flex;
    font-weight: 600;
    height: 16px;
    margin: 0 6px;
    background: var(--vBlue);
    color: var(--vWhite);
    align-items: center;
  }
  .ActionList_caption {
    display: inline;
    text-wrap: nowrap;
    font-weight: 400;
    color: var(--vInkLighter);
    padding-left: 8px;
    align-self: flex-start;
  }
  .ActionList_text {
    font-size: 10px;
    font-weight: 600;
    margin: 0 6px;
    text-overflow: ellipsis;
    overflow-wrap: break-word;
    word-wrap: break-word;
    word-break: break-all;
    hyphens: auto;
    overflow: hidden;
    text-align: center;
    text-transform: uppercase;
  }
  .ActionList_favorite {
    margin-left: 4px;
    height: 16px;
    width: 16px;
    &:hover .ActionList_not-hovered {
      display: none;
    }
    &:not(:hover) .ActionList_hovered {
      display: none;
    }
  }
}

/* src/components/Spinner/Spinner.module.css */
.Spinner_fullscreen {
  display: flex;
  position: fixed;
  align-items: center;
  vertical-align: middle;
  padding: 40vh auto;
  background-color: color-mix(in srgb, var(--vWhite) 80%, transparent);
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
}
.Spinner_centered {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
}
.Spinner_spinner {
  margin: 24px auto;
  position: relative;
  text-align: center;
  border-radius: 100%;
  background-color: var(--vBlue);
  &.Spinner_unknown-progress {
    animation: Spinner_rotate 0.8s infinite linear;
    border: 2px solid var(--vBlue);
    border-right-color: transparent;
    background-color: transparent;
  }
  &.Spinner_inverseColor {
    border-color: var(--vWhite);
    border-right-color: transparent;
  }
  &.Spinner_noMargin {
    margin: 0 auto;
  }
  &.Spinner_small {
    height: 16px;
    width: 16px;
    & > .Spinner_circle {
      height: 12px;
      width: 12px;
      top: 2px;
      left: 2px;
    }
  }
  &.Spinner_medium {
    height: 32px;
    width: 32px;
    & > .Spinner_circle {
      height: 26px;
      width: 26px;
      top: 3px;
      left: 3px;
    }
    &.Spinner_unknown-progress {
      border-width: 3px;
    }
  }
  &.Spinner_large {
    height: 64px;
    width: 64px;
    & > .Spinner_circle {
      height: 56px;
      width: 56px;
      top: 4px;
      left: 4px;
      .Spinner_percent {
        top: 19px;
        font-size: 12px;
      }
    }
    &.Spinner_unknown-progress {
      border-width: 4px;
    }
  }
  &.Spinner_x-large {
    height: 128px;
    width: 128px;
    & > .Spinner_circle {
      height: 114px;
      width: 114px;
      top: 7px;
      left: 7px;
      .Spinner_percent {
        top: 50px;
        font-size: 16px;
      }
    }
    &.Spinner_unknown-progress {
      border-width: 7px;
    }
  }
  .Spinner_circle {
    position: relative;
    text-align: center;
    border-radius: 100%;
    background-color: var(--vWhite);
    .Spinner_percent {
      position: relative;
      color: var(--vBlue);
    }
  }
}
@keyframes Spinner_rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* src/components/Button/Button.module.css */
.Button_button {
  align-items: center;
  border: 1px solid transparent;
  border-radius: 2px;
  box-sizing: border-box;
  cursor: pointer;
  display: flex;
  font-size: 14px;
  font-weight: 600;
  height: 34px;
  justify-content: center;
  min-width: 80px;
  overflow: hidden;
  text-overflow: ellipsis;
  padding: 0 7px;
  text-align: center;
  transition-duration: 0.2s;
  transform: translate3d(0, 0, 0);
  width: auto;
  position: relative;
  &::before {
    content: "";
    display: inline-block;
    vertical-align: middle;
    height: 100%;
  }
  &:not(.Button_subdued, .Button_subdued-compact, .Button_subdued-inverse)::after {
    background-image:
      radial-gradient(
        circle,
        var(--vInkLightest) 10%,
        transparent 10%);
    background-position: 50%;
    background-repeat: no-repeat;
    content: "";
    display: block;
    height: 100%;
    left: 0;
    opacity: 0;
    pointer-events: none;
    position: absolute;
    top: 0;
    transform: scale(10, 10);
    transition: transform 0.3s, opacity 1s;
    width: 100%;
