  &.Popover_padding-medium {
    padding: 16px;
  }
  &.Popover_noPadding {
    padding: 0;
  }
  &.Popover_bottom-left {
    right: 0;
  }
  &.Popover_subdued {
    background-color: var(--vUiHueLighter);
  }
  &.Popover_bottom-right {
    left: 0;
  }
  &.Popover_top-left {
    right: 0;
    bottom: 100%;
  }
  &.Popover_top-right {
    left: 0;
    bottom: 100%;
  }
