  background-color: var(--vWhite);
  position: absolute;
  width: 0;
  height: 0;
  margin: 7px 10px 10px 8px;
}
.Popover_popoverSpeechBubbleInner {
  position: absolute;
  &::after,
  &::before {
    position: absolute;
    left: calc(50% - 8px);
    content: " ";
    border-color: transparent transparent var(--vWhite);
    border-style: solid;
    border-width: 8px;
  }
  &::before {
    top: -16px;
    border-bottom-color: var(--vUiHueDark);
