  &::after {
    top: -15px;
    border-bottom-color: var(--vWhite);
  }
  .Popover_subdued {
    background-color: var(--vUiHueLighter);
  }
  &[data-placement^=bottom] {
    transform: scaleY(-1);
  }
  &[data-placement^=left] {
    transform: rotate(-90deg);
  }
  &[data-placement^=right] {
    transform: rotate(90deg);
  }
}

