      &:hover:has(td[rowspan]) + tr td,
      &:has(+ tr:hover):has(td[rowspan]) td {
        background-color: var(--vUiHueLight) !important;
        [class*=Tag_gray] {
          box-shadow: inset 0 0 0 1px var(--vUiHue);
        }
      }
    }
    td {
      background-color: var(--vWhite);
      transition-property: background;
      transition-duration: 300ms;
      transition-timing-function: ease-in;
      [class*=Tag_gray] {
        transition: box-shadow 300ms ease-in;
      }
      &.DataTable_styled {
        font-size: 14px;
      }
    }
  }
  .DataTable_sticky-header {
    position: sticky;
    top: 0;
    z-index: 1;
    &::before {
      content: "";
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background-color: var(--vUiHue);
      z-index: -1;
    }
    &.DataTable_is-safari {
      &::before {
        display: none;
      }
      th {
        position: relative;
        &::before {
          content: "";
          position: absolute;
          top: -1px;
          left: -1px;
          right: -1px;
          bottom: -1px;
          background-color: var(--vUiHue);
          z-index: -1;
        }
      }
    }
  }
}
