/* src/components/Chart/Chart.module.css */
.Chart_spinner {
  padding: 60px 0;
}
.Chart_chart {
  background-color: var(--vWhite);
  &.Chart_framed-full {
    border: 1px solid var(--vUiHue);
  }
  &.Chart_framed-top {
    border-top: 1px solid var(--vUiHue);
  }
  *:focus {
    outline: none;
  }
}
.Chart_zero-state {
  position: relative;
  &.Chart_line-chart-mock {
    background-image: url(data:image/png;base64,);
    background-repeat: no-repeat;
    background-position: 12px 50px;
    &::before {
      content: " ";
      width: calc(100% - 106px);
      height: 100%;
      background-image: url(data:image/png;base64,);
      background-repeat: repeat no-repeat;
      background-position: left 54px;
      position: absolute;
      top: 0;
      left: 94px;
      display: block;
      box-sizing: border-box;
    }
  }
  &.Chart_pie-chart-mock {
    background-image: url(data:image/png;base64,);
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
  }
}
.Chart_top-panel {
  height: 48px;
  background-color: var(--vUiHueLighter);
  text-align: left;
  padding: 8px;
  border-bottom: 1px solid var(--vUiHue);
  overflow: hidden;
}
[class*=Label_label] + .Chart_wrapper {
  margin-top: 8px;
}
:root[theme=dark] {
  .Chart_zero-state {
    &.Chart_line-chart-mock,
    &.Chart_pie-chart-mock {
      mix-blend-mode: overlay;
    }
  }
}

/* src/components/SelectionList/components/PureSelectionList/PureSelectionList.module.css */
.PureSelectionList_wrapper {
  font-size: 12px;
  justify-content: center;
  overflow-y: auto;
  min-width: 200px;
  &:hover li.PureSelectionList_active:not(:hover) {
    background: inherit !important;
    a {
      color: var(--vInk) !important;
    }
    .PureSelectionList_caption {
      color: var(--vInkLighter) !important;
    }
    path,
    polygon,
    circle,
    rect {
      fill: var(--vBlue) !important;
    }
  }
  &.PureSelectionList_noMinWidth {
    min-width: 0;
  }
  ul {
    list-style-type: none;
    padding: 0;
    margin: 0 0 8px;
    &:not(:last-of-type) {
      border-bottom: 1px solid var(--vUiHueDark);
    }
    &:last-child {
      margin-bottom: 0;
      li:last-child {
        margin-bottom: 0;
      }
    }
    li {
      cursor: pointer;
      &:last-child {
        margin-bottom: 8px;
      }
      .PureSelectionList_item-button {
        position: relative;
        right: 10px;
      }
      .PureSelectionList_item-ctn {
        display: flex;
      }
      .PureSelectionList_item-text {
        width: 100%;
      }
      .PureSelectionList_item-text-column {
        display: flex;
        flex-direction: row;
        align-items: center;
        overflow: hidden;
        white-space: nowrap;
      }
      a {
        align-items: center;
        padding: 6px 8px;
        color: var(--vInk);
        text-decoration: none;
        font-weight: 600;
        font-size: 14px;
        overflow: hidden;
        white-space: nowrap;
        text-overflow: ellipsis;
        display: block;
        .PureSelectionList_not-selected {
          padding-left: 24px;
        }
        .PureSelectionList_not-selected,
        .PureSelectionList_selected {
          white-space: nowrap;
          text-overflow: ellipsis;
          overflow: hidden;
          display: block;
        }
        span {
          margin-right: 8px;
          display: inherit;
          line-height: 20px;
        }
        .PureSelectionList_wrap {
          white-space: normal;
          word-break: break-word;
        }
        .PureSelectionList_caption {
          font-weight: 400;
          color: var(--vInkLighter);
          font-size: 12px;
          padding-left: 24px;
          padding-top: 2px;
          line-height: 16px;
          white-space: wrap;
          text-align: left;
        }
      }
      &.PureSelectionList_disabled {
        cursor: not-allowed;
        a {
          color: var(--vInkLightest);
          .PureSelectionList_caption {
            color: var(--vInkLightest);
          }
        }
      }
      &.PureSelectionList_group-label {
        &:hover:not(&.PureSelectionList_disabled) {
          cursor: initial;
          background: var(--vWhite);
          a {
            color: var(--vInkLighter);
          }
        }
        a {
          color: var(--vInkLighter);
          text-transform: uppercase;
          font-size: 12px;
        }
      }
      &:hover:not(&.PureSelectionList_disabled),
      &.PureSelectionList_active {
        background: var(--vBlue);
        a {
          color: var(--vWhite);
        }
        .PureSelectionList_caption {
          color: var(--vWhite);
        }
        path,
        polygon,
        circle,
        rect {
          fill: var(--vWhite);
        }
      }
    }
  }
}

/* src/components/SelectionList/components/SelectionListWrapper/SelectionListWrapper.module.css */
.SelectionListWrapper_spinner-wrapper {
  margin: 32px;
}

/* src/components/DraggableDataBlock/DraggableDataBlock.module.css */
.DraggableDataBlock_area {
  background: transparent;
  width: 100%;
  &.DraggableDataBlock_extendedArea {
    padding: 16px 0;
  }
  &.DraggableDataBlock_narrow {
    width: auto;
    .DraggableDataBlock_fake-dropzone {
      width: 188px;
    }
  }
  &.DraggableDataBlock_wide {
    width: auto;
    .DraggableDataBlock_fake-dropzone {
      width: 270px;
    }
  }
  .DraggableDataBlock_fake-dropzone {
    position: relative;
    &.DraggableDataBlock_dropped {
      border: 1px dashed var(--vUiHueDark);
      background-color: var(--vUiHueLighter);
      color: var(--vInkLighter);
      &.DraggableDataBlock_margin-h-half {
        margin-left: -2px;
        margin-right: -2px;
      }
      &.DraggableDataBlock_margin-h-full {
        margin-left: 2px;
        margin-right: 2px;
      }
      &.DraggableDataBlock_margin-v-half {
        margin-top: -2px;
        margin-bottom: -2px;
      }
      &.DraggableDataBlock_margin-v-full {
        margin-top: 2px;
        margin-bottom: 2px;
      }
      &.DraggableDataBlock_dropped-type-dimension {
        border: 1px dashed var(--vGreen);
        background: var(--vGreenLight);
        box-shadow: inset 0 0 12px 0 var(--vGreen);
      }
      &.DraggableDataBlock_dropped-type-metric {
        border: 1px dashed var(--vBlue);
        background: var(--vBlueLight);
        box-shadow: inset 0 0 12px 0 var(--vBlue);
      }
      &.DraggableDataBlock_dropped-type-attribute {
        border: 1px dashed var(--vViolet);
        background: var(--vVioletLight);
        box-shadow: inset 0 0 12px 0 var(--vViolet);
      }
      &.DraggableDataBlock_dropped-type-event {
        border: 1px dashed var(--vPinkDark);
        background: var(--vPinkLight);
        box-shadow: inset 0 0 12px 0 var(--vPinkDark);
      }
      &.DraggableDataBlock_dropped-type-consent-type {
        border: 1px dashed var(--vBluebonnet);
        background: var(--vBluebonnetLight);
        box-shadow: inset 0 0 12px 0 var(--vBluebonnet);
      }
      &.DraggableDataBlock_droppedErrored {
        border-color: var(--vRed);
      }
      &.DraggableDataBlock_subdued {
        box-shadow: none;
      }
      .DraggableDataBlock_wrapper {
        width: calc(100% - 8px);
        margin: 4px;
      }
    }
    &.DraggableDataBlock_margin-h-half {
      margin-left: 4px;
      margin-right: 4px;
    }
    &.DraggableDataBlock_margin-h-full {
      margin-left: 8px;
      margin-right: 8px;
    }
    &.DraggableDataBlock_margin-v-half {
      margin-top: 4px;
      margin-bottom: 4px;
    }
    &.DraggableDataBlock_margin-v-full {
      margin-top: 8px;
      margin-bottom: 8px;
    }
  }
  .DraggableDataBlock_wrapper {
    width: 100%;
    height: 24px;
    line-height: 22px;
    font-size: 12px;
    font-weight: 600;
    text-align: center;
    cursor: grab;
    box-shadow: 0 1px 1px 0 rgb(0 0 0 / 20%);
    position: relative;
    border-radius: 2px;
    color: var(--vInkAlwaysDark);
    &.DraggableDataBlock_type-dimension {
      border: 1px solid var(--vGreen);
      background: linear-gradient(color-mix(in srgb, var(--vGreen) 14%, var(--vAlwaysWhite)), color-mix(in srgb, var(--vGreen) 36%, var(--vAlwaysWhite)));
    }
    &.DraggableDataBlock_type-metric {
      border: 1px solid var(--vBlueActive);
      background: linear-gradient(color-mix(in srgb, var(--vBlue) 14%, var(--vAlwaysWhite)), color-mix(in srgb, var(--vBlue) 36%, var(--vAlwaysWhite)));
    }
    &.DraggableDataBlock_type-attribute {
      border: 1px solid var(--vVioletDark);
      background: linear-gradient(color-mix(in srgb, var(--vViolet) 14%, var(--vAlwaysWhite)), color-mix(in srgb, var(--vViolet) 36%, var(--vAlwaysWhite)));
    }
    &.DraggableDataBlock_type-event {
      border: 1px solid var(--vPinkDark);
      background: linear-gradient(color-mix(in srgb, var(--vPink) 14%, var(--vAlwaysWhite)), color-mix(in srgb, var(--vPink) 36%, var(--vAlwaysWhite)));
    }
    &.DraggableDataBlock_type-consent-type {
      border: 1px solid var(--vBluebonnet);
      background: linear-gradient(color-mix(in srgb, var(--vBluebonnet) 14%, var(--vAlwaysWhite)), color-mix(in srgb, var(--vBluebonnet) 36%, var(--vAlwaysWhite)));
    }
    &.DraggableDataBlock_inactive {
      opacity: 0.5;
      cursor: not-allowed;
    }
    .DraggableDataBlock_icon-dots {
      margin: 3px 0;
      display: block;
      &.DraggableDataBlock_icon-left {
        float: left;
      }
      &.DraggableDataBlock_icon-right {
        float: right;
      }
    }
    .DraggableDataBlock_content-selection {
      user-select: none;
      max-width: calc(100% - 36px);
      display: inline-block;
      vertical-align: middle;
      margin-top: -2px;
    }
    .DraggableDataBlock_info-icon-left {
      vertical-align: top;
      position: relative;
      top: 2px;
      margin-right: 4px;
    }
  }
}
.DraggableDataBlock_content-text {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: calc(100% - 36px);
  display: inline-block;
  user-select: none;
}
:root[theme=dark] {
  .DraggableDataBlock_area .DraggableDataBlock_wrapper {
    &.DraggableDataBlock_type-dimension {
      border-color: var(--vGreenLight);
      background: linear-gradient(var(--vGreen), var(--vGreenDark));
    }
    &.DraggableDataBlock_type-metric {
      border-color: var(--vBlueLight);
      background: linear-gradient(var(--vBlue), var(--vBlueDark));
    }
    &.DraggableDataBlock_type-attribute {
      border-color: var(--vVioletLight);
      background: linear-gradient(#c699ff, #ab75f0);
    }
    &.DraggableDataBlock_type-event {
      border-color: var(--vPinkLight);
      background: linear-gradient(var(--vPink), var(--vPinkDark));
    }
    &.DraggableDataBlock_type-consent-type {
      border-color: var(--vBluebonnetLight);
      background: linear-gradient(var(--vBluebonnet), #626bda);
    }
  }
}

/* src/components/DraggableDataBlock/components/Button.module.css */
.Button_button2 {
  height: 16px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  line-height: normal;
  flex-wrap: nowrap;
  padding: 0 10px;
  gap: 4px;
}
.Button_green {
  border: 1px solid var(--vGreen);
  background: linear-gradient(var(--vWhite), color-mix(in srgb, var(--vGreen) 17%, var(--vWhite)));
  &:hover {
    background: linear-gradient(color-mix(in srgb, var(--vGreen) 9%, var(--vWhite)), color-mix(in srgb, var(--vGreen) 17%, var(--vWhite)));
    border-color: color-mix(in srgb, var(--vGreen) 80%, var(--vInk));
  }
  &.Button_active2 {
    background: linear-gradient(color-mix(in srgb, var(--vGreen) 17%, var(--vWhite)), var(--vWhite));
  }
}
.Button_blue {
  border: 1px solid var(--vBlue);
  background: linear-gradient(var(--vWhite), color-mix(in srgb, var(--vBlue) 17%, var(--vWhite)));
  &:hover {
    background: linear-gradient(color-mix(in srgb, var(--vBlue) 9%, var(--vWhite)), color-mix(in srgb, var(--vBlue) 17%, var(--vWhite)));
    border-color: color-mix(in srgb, var(--vBlue) 80%, var(--vInk));
  }
  &.Button_active2 {
