    &.Button_active2 {
      background: linear-gradient(var(--vBlue), color-mix(in srgb, var(--vBlue) 58%, var(--vAlwaysWhite)));
    }
  }
  .Button_dark-violet {
    background: linear-gradient(color-mix(in srgb, var(--vViolet) 58%, var(--vAlwaysWhite)), var(--vViolet));
    &:hover {
      background: var(--vViolet);
    }
    &.Button_active2 {
      background: linear-gradient(var(--vViolet), color-mix(in srgb, var(--vViolet) 58%, var(--vAlwaysWhite)));
    }
  }
  .Button_dark-pink {
    background: linear-gradient(color-mix(in srgb, var(--vPink) 58%, var(--vAlwaysWhite)), var(--vPink));
    &:hover {
      background: var(--vPink);
    }
    &.Button_active2 {
      background: linear-gradient(var(--vPink), color-mix(in srgb, var(--vPink) 58%, var(--vAlwaysWhite)));
