/* src/components/DataBlockDropzone/DataBlockDropzone.module.css */
.DataBlockDropzone_area {
  background: transparent;
  width: 100%;
  &.DataBlockDropzone_narrow {
    width: auto;
    .DataBlockDropzone_wrapper {
      width: 212px;
    }
  }
  &.DataBlockDropzone_wide {
    width: auto;
    .DataBlockDropzone_wrapper {
      width: 294px;
    }
  }
  .DataBlockDropzone_wrapper {
    width: 100%;
    height: 32px;
    line-height: 28px;
    text-align: center;
    font-size: 14px;
    font-weight: 400;
    &.DataBlockDropzone_type-dimension {
      border: 1px dashed var(--vGreen);
      background-color: var(--vGreenLight);
      color: var(--vGreen);
      box-shadow: inset 0 0 12px 0 var(--vGreen);
      &.DataBlockDropzone_subdued {
        box-shadow: none;
      }
    }
    &.DataBlockDropzone_type-metric {
      border: 1px dashed var(--vBlue);
      background-color: var(--vBlueLight);
      color: var(--vBlue);
      box-shadow: inset 0 0 12px 0 var(--vBlue);
      &.DataBlockDropzone_subdued {
        box-shadow: none;
      }
    }
    &.DataBlockDropzone_type-attribute {
      border: 1px dashed var(--vViolet);
      background-color: var(--vVioletLight);
      color: var(--vViolet);
      box-shadow: inset 0 0 12px 0 var(--vViolet);
      &.DataBlockDropzone_subdued {
        box-shadow: none;
      }
    }
    &.DataBlockDropzone_type-event {
      border: 1px dashed var(--vPinkDark);
      background-color: var(--vPinkLight);
      color: var(--vPinkDark);
      box-shadow: inset 0 0 12px 0 var(--vPinkDark);
      &.DataBlockDropzone_subdued {
        box-shadow: none;
      }
    }
    &.DataBlockDropzone_type-consent-type {
      border: 1px dashed var(--vBluebonnet);
      background-color: var(--vBluebonnetLight);
      color: var(--vBluebonnet);
      box-shadow: inset 0 0 12px 0 var(--vBluebonnet);
      &.DataBlockDropzone_subdued {
        box-shadow: none;
      }
    }
    &.DataBlockDropzone_type-inactive,
    &.DataBlockDropzone_type-forbidden {
      border: 1px dashed var(--vUiHueDark);
      background-color: var(--vUiHueLighter);
      color: var(--vInkLighter);
    }
    &.DataBlockDropzone_type-forbidden {
      cursor: not-allowed;
    }
    &.DataBlockDropzone_type-disabled {
      border: 1px dashed var(--vUiHue);
      background-color: var(--vUiHueLighter);
      color: var(--vUiHueDark);
      box-shadow: none;
    }
    &.DataBlockDropzone_margin-h-half {
      margin-left: 4px;
      margin-right: 4px;
    }
    &.DataBlockDropzone_margin-h-full {
      margin-left: 8px;
      margin-right: 8px;
    }
    &.DataBlockDropzone_margin-v-half {
      margin-top: 4px;
      margin-bottom: 4px;
    }
    &.DataBlockDropzone_margin-v-full {
      margin-top: 8px;
      margin-bottom: 8px;
    }
    &.DataBlockDropzone_doubleHeight {
      height: 64px;
      line-height: 60px;
      .DataBlockDropzone_content {
        white-space: normal;
        line-height: 16px;
        vertical-align: middle;
      }
    }
  }
}
.DataBlockDropzone_content {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: calc(100% - 16px);
  display: inline-block;
}

/* src/components/DraggableListBlock/DraggableListBlock.module.css */
.DraggableListBlock_area {
  background: transparent;
  width: 100%;
  &.DraggableListBlock_extendedArea {
    padding: 16px 0;
  }
  .DraggableListBlock_fake-dropzone {
    position: relative;
  }
  .DraggableListBlock_wrapper {
    width: 100%;
    height: 48px;
    font-weight: 600;
    cursor: grab;
    position: relative;
    border-radius: 1px;
    color: var(--vInk);
    padding: 0 16px 0 8px;
    border: 1px solid var(--vUiHue);
    display: flex;
    align-items: center;
    justify-content: center;
    &.DraggableListBlock_inactive {
      opacity: 0.5;
    }
    .DraggableListBlock_icon-dots {
      display: block;
      margin-right: 8px;
      &.DraggableListBlock_icon-left {
        float: left;
      }
    }
    .DraggableListBlock_content-selection {
      user-select: none;
      max-width: calc(100% - 36px);
      display: inline-block;
      margin-top: -2px;
    }
    .DraggableListBlock_info-icon-left {
      vertical-align: top;
      position: relative;
      top: 2px;
      margin-right: 4px;
    }
    .DraggableListBlock_children {
      width: 100%;
    }
  }
}
.DraggableListBlock_content-text {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  max-width: calc(100% - 36px);
  display: inline-block;
  user-select: none;
}
.DraggableListBlock_no-select {
  user-select: none;
}

/* src/components/Preloader/Preloader.module.css */
.Preloader_preloader {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background-color: var(--vWhite);
}

/* src/components/Information/Information.module.css */
.Information_wrapper {
  font-size: 12px;
  line-height: 14px;
  width: 100%;
  &.Information_error {
    border-left: 4px solid var(--vRed);
    background-color: var(--vRedLight);
  }
  &.Information_warning {
    border-left: 4px solid var(--vYellow);
    background-color: var(--vYellowLight);
  }
  &.Information_success {
    border-left: 4px solid var(--vGreen);
    background-color: var(--vGreenLight);
  }
  &.Information_info {
    border-left: 4px solid var(--vBlue);
    background-color: var(--vBlueLight);
  }
  .Information_wrapper-inside {
    padding: 8px 7px 8px 12px;
    border-left: none;
    .Information_icon {
      margin-right: 4px;
    }
    .Information_text {
      padding-top: 2px;
      color: var(--vInk);
    }
  }
}

/* src/components/ProgressBar/ProgressBar.module.css */
.ProgressBar_wrapper {
  width: 100%;
  .ProgressBar_title-container {
    width: 100%;
    display: flex;
    justify-content: space-between;
    .ProgressBar_title {
      font-size: 12px;
      color: var(--vInk);
      flex: 1;
    }
    .ProgressBar_caption {
      font-size: 12px;
      max-width: 50%;
      color: var(--vInkLighter);
    }
  }
  .ProgressBar_bar {
    margin: 2px 0;
    width: 100%;
    height: 8px;
    border-radius: 4px;
    box-shadow: inset 0 1px 3px 0 color-mix(in srgb, var(--vUiHueDark) 50%, transparent);
    overflow: hidden;
    > div {
      height: 8px;
      border-radius: 4px;
    }
    .ProgressBar_endless {
      width: 100%;
      position: relative;
      animation: ProgressBar_move 2s infinite linear;
    }
  }
  .ProgressBar_footer-container {
    width: 100%;
    font-size: 12px;
    display: flex;
    .ProgressBar_status {
      font-size: 14px;
      color: var(--vBlue);
      flex: 1 1;
      &.ProgressBar_ratio {
        color: var(--vGreen);
      }
      &.ProgressBar_blue {
        color: var(--vBlue);
      }
      &.ProgressBar_orange {
        color: var(--vOrange);
      }
      &.ProgressBar_red {
        color: var(--vRed);
      }
    }
    .ProgressBar_sidenote {
      color: var(--vInkLighter);
      width: auto;
      &.ProgressBar_ratio {
        color: var(--vRed);
      }
    }
  }
}
.ProgressBar_title,
.ProgressBar_caption {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}
@keyframes ProgressBar_move {
  0% {
    left: -100%;
  }
  100% {
    left: 100%;
  }
}

/* src/components/Link/Link.module.css */
.Link_default {
  color: var(--vBlue);
  cursor: pointer;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
  &:hover {
    text-decoration: underline;
  }
}
.Link_small {
  font-size: 12px;
}
.Link_medium {
  font-size: 14px;
}
.Link_large {
  font-size: 18px;
}
.Link_breakLongContent {
  word-break: break-word;
  white-space: initial;
}
.Link_showWhiteSpace {
  white-space: pre;
}

/* src/components/HelpLink/HelpLink.module.css */
.HelpLink_wrapper {
  display: inline-flex;
  align-items: center;
  max-width: 640px;
  background-color: var(--vWhite);
  border: 1px solid var(--vUiHueLight);
  border-radius: 24px;
  padding: 8px;
  padding-right: 12px;
  .HelpLink_label {
    margin-left: 8px;
    margin-right: 4px;
    font-size: 12px;
    font-weight: 400;
  }
  * {
    white-space: nowrap;
    line-height: 16px;
  }
}

/* src/components/StatusBar/StatusBar.module.css */
.StatusBar_wrapper {
  justify-content: center;
  align-items: center;
  width: 100%;
  font-size: 12px;
  word-wrap: break-word;
  font-weight: 600;
  text-align: center;
  padding: 8px;
  line-height: 14px;
  &.StatusBar_noPadding {
    padding: 0;
  }
  &.StatusBar_noChildren {
    padding: 3px;
    button {
      height: 24px;
      font-size: 12px;
    }
    .StatusBar_white-icon {
      path,
      polygon,
      circle,
      rect {
        fill: var(--vWhite) !important;
      }
    }
    .StatusBar_default-icon {
      path,
      polygon,
      circle,
      rect {
        fill: var(--vInk) !important;
      }
    }
    .StatusBar_always-default-icon {
      path,
      polygon,
      circle,
      rect {
        fill: var(--vInkAlwaysDark) !important;
      }
    }
    .StatusBar_text {
      height: 24px;
      line-height: 24px;
    }
    .StatusBar_link {
      text-decoration: underline;
      cursor: pointer;
      &:hover {
        opacity: 0.8;
      }
    }
  }
  &.StatusBar_default {
    box-shadow: inset 0 1px 0 0 var(--vUiHueDark), inset 0 -1px 0 0 var(--vUiHueDark);
    background-color: var(--vWhite);
    color: var(--vInk);
  }
  &.StatusBar_information {
    background-color: var(--vBlue);
    color: var(--vWhite);
    box-shadow: inset 0 1px 0 0 var(--vBlueDark), inset 0 -1px 0 0 var(--vBlueDark);
  }
  &.StatusBar_warning {
    background-color: var(--vYellow);
    color: var(--vInkAlwaysDark);
    box-shadow: inset 0 1px 0 0 var(--vYellowDark), inset 0 -1px 0 0 var(--vYellowDark);
  }
  &.StatusBar_error {
    background-color: var(--vRed);
    color: var(--vWhite);
    box-shadow: inset 0 1px 0 0 var(--vRedDark), inset 0 -1px 0 0 var(--vRedDark);
  }
  &.StatusBar_success {
    background-color: var(--vGreen);
    color: var(--vWhite);
    box-shadow: inset 0 1px 0 0 var(--vGreenDark), inset 0 -1px 0 0 var(--vGreenDark);
  }
}
.StatusBar_cutText {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}

/* src/components/RadioButtonGroup/RadioButtonGroup.module.css */
.RadioButtonGroup_items {
  display: grid;
  gap: 8px;
}
.RadioButtonGroup_additionalContent {
  margin-top: 16px;
}

/* src/components/RadioButtonGroup/components/RadioItem/RadioItem.module.css */
.RadioItem_wrapper {
  display: grid;
  grid-template-columns: 16px auto;
  gap: 4px 8px;
  align-items: center;
  &:has(input:disabled) > label {
    color: var(--vInkLightest);
  }
}
.RadioItem_caption {
  grid-column: 2;
}

/* src/components/Card/Card.module.css */
.Card_sections > :last-child {
  border-bottom: 1px solid var(--vUiHue);
  box-shadow: inset 0 0 0 0 var(--vUiHue);
}
.Card_wrapper:not(.Card_connected) + .Card_wrapper {
  margin-top: 24px;
}
.Card_wrapper.Card_connected::after {
  content: "";
  display: block;
  width: 0;
  height: 24px;
  border-left: 1px solid var(--vUiHue);
  position: relative;
  left: 36px;
}

/* src/components/Card/components/CardSection/CardSection.module.css */
.CardSection_wrapper {
  border: 1px solid var(--vUiHue);
  border-bottom: none;
  border-radius: 1px;
  background-color: var(--vWhite);
  &.CardSection_subdued {
    background-color: var(--vUiHueLighter);
  }
  &.CardSection_primary {
    background-color: var(--vBlue);
    border: 1px solid var(--vBlueDark);
  }
  &.CardSection_padding-none {
    padding: 0;
  }
  &.CardSection_padding-narrow {
    padding: 16px;
  }
  &.CardSection_padding-medium {
    padding: 24px;
  }
  &.CardSection_padding-wide {
    padding: 32px;
  }
  &.CardSection_padding-extraWide {
    padding: 40px;
  }
}

/* src/components/Card/components/CardAccordion/CardAccordion.module.css */
.CardAccordion_wrapper {
  border: 1px solid var(--vUiHue);
  border-bottom: none;
  border-radius: 1px;
  background-color: var(--vWhite);
  &.CardAccordion_subdued {
    background-color: var(--vUiHueLighter);
  }
  .CardAccordion_expandableContent {
    padding: 24px;
  }
  .CardAccordion_clickableElement {
    display: flex;
    align-items: center;
    padding: 24px;
    border-radius: 1px;
    cursor: pointer;
    &.CardAccordion_opened {
      border-bottom: 1px solid var(--vUiHue);
    }
  }
  .CardAccordion_button {
    display: flex;
    margin-right: 16px;
    .CardAccordion_rotate-transition {
      transition: all 200ms linear;
    }
    .CardAccordion_rotate-down {
      transform: rotate(90deg);
    }
    .CardAccordion_rotate-up {
      transform: rotate(0deg);
    }
  }
}

/* src/components/TextArea/TextArea.module.css */
.TextArea_textarea {
  display: block;
  width: 100%;
  padding: 8px;
  border: 1px solid var(--vUiHueDark);
  border-radius: 2px;
  background-color: var(--vWhite);
  overflow-y: auto;
  overflow-x: hidden;
  resize: none;
  font-size: var(--vInputFontSize);
  color: var(--vInk);
  line-height: 16px;
  outline: none;
  &:focus-visible {
    border-color: var(--vBlue);
  }
  &.TextArea_disabled {
    color: var(--vInkLightest);
    border-color: var(--vUiHue);
    background-color: var(--vUiHueLighter);
    cursor: not-allowed;
  }
  &.TextArea_invalid {
    color: var(--vRed);
    border-color: var(--vRed);
  }
}

/* src/components/Switcher/Switcher.module.css */
.Switcher_wrapper {
  display: flex;
  &:has(:focus-visible) {
    .Switcher_background {
      outline: var(--vOutlineColor) var(--vOutlineStyle) var(--vOutlineWidth);
      outline-offset: var(--vOutlineOffset);
    }
    input:focus-visible {
      outline: none;
    }
  }
  .Switcher_switch {
    position: absolute;
    display: flex;
    justify-content: center;
    align-items: center;
    border-radius: 9999px;
    background-color: var(--vWhite);
    box-shadow: 0 1px 3px 0 rgba(52 63 73 / 20%);
    transition: 0.5s;
    &.Switcher_checked:not(&.Switcher_onHold) {
      box-shadow: 0 1px 3px 0 rgba(12 108 19 / 40%);
    }
    &.Switcher_onHold {
      box-shadow: 0 1px 3px 0 rgba(52 63 73 / 20%);
      &.Switcher_checked {
        box-shadow: 0 1px 3px 0 rgba(36 42 46 / 40%);
      }
    }
    &.Switcher_small {
      width: 20px;
      height: 20px;
      left: 2px;
      span,
      svg {
        width: 10px;
        height: 10px;
        line-height: 9px;
      }
      &.Switcher_checked {
        left: 22px;
      }
    }
    &.Switcher_medium {
      width: 27px;
      height: 27px;
      left: 3px;
      span,
      svg {
        width: 13px;
        height: 13px;
        line-height: 13px;
      }
      &.Switcher_checked {
        left: 29px;
      }
    }
    &.Switcher_large {
      width: 34px;
      height: 34px;
      left: 3px;
      span,
      svg {
        width: 16px;
        height: 16px;
        line-height: 16px;
      }
      &.Switcher_checked {
        left: 37px;
      }
    }
  }
}
.Switcher_switcher-checkbox {
  appearance: none;
  position: absolute;
}
.Switcher_background {
  position: relative;
  display: inline-flex;
  align-items: center;
  background-color: var(--vUiHueDark);
  box-shadow: 0 1px 2px 0 rgba(102 102 102 / 10%) inset;
  border-radius: 9999px;
  cursor: pointer;
  transition: 0.5s;
  &.Switcher_small {
    width: 44px;
    height: 24px;
  }
  &.Switcher_medium {
    width: 59px;
    height: 33px;
  }
  &.Switcher_large {
    width: 74px;
    height: 40px;
  }
  path,
  polygon,
  circle,
  rect {
    fill: var(--vInkLightest);
  }
  &.Switcher_onHold {
    background-color: var(--vUiHue);
    box-shadow: 0 1px 2px 0 rgba(102 102 102 / 10%) inset;
    &.Switcher_checked {
      background-color: var(--vInkLighter);
      box-shadow: 0 1px 2px 0 rgba(36 42 46 / 40%) inset;
      path,
      polygon,
      circle,
      rect {
        fill: var(--vInkLighter);
      }
    }
    rect {
      fill: var(--vUiHue);
    }
  }
  &.Switcher_checked:not(&.Switcher_onHold) {
    background-color: var(--vGreen);
    box-shadow: 0 1px 2px 0 rgba(12 108 19 / 40%) inset;
    path,
    polygon,
    circle,
    rect {
      fill: var(--vGreen);
    }
  }
  &.Switcher_disabled {
    opacity: 0.4;
    cursor: not-allowed;
  }
}

/* src/components/Skeleton/Skeleton.module.css */
:root {
  --skelGradStart: 20%;
  --skelGradEnd: 50%;
}
.Skeleton_skeleton-box {
  display: inline-block;
  position: relative;
  overflow: hidden;
  background-color: var(--vUiHue);
  border-radius: 8px;
  &.Skeleton_roundBorder {
    border-radius: 9999px;
  }
  &::after {
    position: absolute;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    transform: translateX(-100%);
    background-image:
      linear-gradient(
        90deg,
        color-mix(in srgb, var(--vAlwaysWhite) 0%, transparent) 0%,
        color-mix(in srgb, var(--vAlwaysWhite) var(--skelGradStart), transparent) 20%,
        color-mix(in srgb, var(--vAlwaysWhite) var(--skelGradEnd), transparent) 60%,
        color-mix(in srgb, var(--vAlwaysWhite) 0%, transparent));
    animation: Skeleton_shimmer 2s infinite;
    content: "";
  }
  @keyframes Skeleton_shimmer {
    100% {
      transform: translateX(100%);
    }
  }
}
:root[theme=dark] {
  --skelGradStart: 4%;
  --skelGradEnd: 10%;
}

/* src/components/Toggler/Toggler.module.css */
.Toggler_wrapper {
  display: inline-block;
  cursor: pointer;
  height: 26px;
  &:has(:focus-visible) {
    outline: var(--vOutlineColor) var(--vOutlineStyle) var(--vOutlineWidth);
    outline-offset: var(--vOutlineOffset);
    input:focus-visible {
      outline: none;
    }
  }
  .Toggler_toggler-checkbox {
    appearance: none;
    position: absolute;
  }
  .Toggler_background {
    display: inline-flex;
    margin: 8px 0;
    height: 10px;
    width: 56px;
    box-shadow: inset 0 2px 2px 0 rgb(0 0 0 / 5%);
    background-color: var(--vUiHue);
    border-radius: 5px;
    align-items: center;
    &.Toggler_checked .Toggler_switch {
      margin-left: 33px;
      left: 1px;
    }
    &.Toggler_default {
      background-color: var(--vUiHue);
      border: 1px solid var(--vUiHueDark);
