  }
  .Toggler_switch {
    width: 22px;
    height: 22px;
    border-radius: 16px;
    box-shadow: 0 1px 1px 0 rgb(0 0 0 / 10%);
    transition: margin 150ms linear;
    position: relative;
    left: -1px;
    &.Toggler_default {
      background-color: var(--vWhite);
      border: 1px solid var(--vUiHueDark);
    }
    &.Toggler_primary {
      background-color: var(--vWhite);
      border: 1px solid var(--vBlueDark);
    }
    &.Toggler_disabled {
      border-color: var(--vUiHue);
