    font-size: 10px;
    border-radius: 16px;
    line-height: 14px;
    .Badge_innerBadge {
      height: 16px;
      .Badge_text.Badge_truncate {
        max-width: 100px;
      }
    }
  }
  &.Badge_black {
    background-color: var(--vInk);
    --dotColor: var(--vWhite);
  }
  &.Badge_purple {
    background-color: var(--vPurple);
    color: var(--vWhite);
    --dotColor: var(--vWhite);
  }
  &.Badge_purple-inverted {
    background-color: var(--vWhite);
    color: var(--vPurple);
    --dotColor: var(--vPurple);
  }
  &.Badge_blue {
    background-color: var(--vBlue);
    color: var(--vWhite);
    --dotColor: var(--vWhite);
  }
  &.Badge_blue-inverted {
    background-color: var(--vWhite);
    color: var(--vBlue);
  }
  &.Badge_green {
    background-color: var(--vGreen);
    color: var(--vWhite);
    --dotColor: var(--vWhite);
  }
  &.Badge_light-green {
    background-color: var(--vGreenLight);
    color: var(--vGreenDark);
    --dotColor: var(--vGreenDark);
  }
  &.Badge_gray {
    background-color: var(--vUiHue);
    color: var(--vInk);
  }
  &.Badge_green-inverted {
    background-color: var(--vWhite);
    color: var(--vGreen);
    border: 1px solid color-mix(in srgb, var(--vGreen) 20%, transparent);
    --dotColor: var(--vGreen);
  }
  &.Badge_light-gray {
    background-color: var(--vWhite);
    color: var(--vInkLighter);
    border: 1px solid var(--vUiHueLight);
  }
  &.Badge_light-blue {
    background-color: var(--vBlueLight);
    color: var(--vBlue);
    --dotColor: var(--vBlue);
  }
  &.Badge_white {
    background-color: var(--vWhite);
    color: var(--vInk);
    border: 1px solid var(--vUiHue);
  }
  &.Badge_disabled {
    opacity: 0.4;
  }
  &.Badge_white,
  &.Badge_green-inverted,
  &.Badge_light-gray {
    .Badge_dot,
    .Badge_text,
    .Badge_icon {
      margin-bottom: 2px;
    }
  }
  .Badge_innerBadge {
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 6px;
    .Badge_text {
      &.Badge_truncate {
        text-overflow: ellipsis;
        overflow: hidden;
        white-space: nowrap;
        max-width: 188px;
      }
    }
    .Badge_icon {
      display: flex;
      justify-content: center;
      align-items: center;
    }
    .Badge_icon-left {
      margin-right: 4px;
    }
    .Badge_icon-right {
      margin-left: 4px;
    }
    .Badge_dot {
      border-radius: 50%;
      display: flex;
      margin-right: 11px;
      margin-left: 5px;
      justify-content: center;
      align-items: center;
      width: 6px;
      height: 6px;
      background-color: var(--dotColor, var(--vBlue));
      animation: Badge_dotPulse 1.5s infinite ease-in-out;
    }
  }
}
@keyframes Badge_dotPulse {
  0% {
    transform: scale(0.95);
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--dotColor, var(--vBlue)) 70%, transparent);
  }
  70% {
    transform: scale(1);
    box-shadow: 0 0 0 6px color-mix(in srgb, var(--dotColor, var(--vBlue)) 0%, transparent);
  }
  100% {
    transform: scale(0.95);
    box-shadow: 0 0 0 0 color-mix(in srgb, var(--dotColor, var(--vBlue)) 0%, transparent);
  }
}

