.SegmentedSelection_wrapper {
  position: relative;
  display: inline-flex;
  border-radius: 3px;
  background: var(--vUiHue);
  padding: 2px;
  &.SegmentedSelection_fullWidth:not(.SegmentedSelection_equalWidth) {
    width: 100%;
    .SegmentedSelection_item {
      flex: 1 1 auto;
    }
  }
  &.SegmentedSelection_equalWidth {
    justify-content: space-between;
    width: 100%;
    .SegmentedSelection_item {
      width: 100%;
    }
