    cursor: pointer;
    white-space: nowrap;
    text-align: center;
    min-width: 28px;
    padding: 0 8px;
    justify-content: center;
    align-items: center;
    width: auto;
    overflow: hidden;
    &:hover,
    &.SegmentedSelection_selected {
      color: var(--vInk);
    }
    &.SegmentedSelection_disabled {
      cursor: not-allowed;
      opacity: 0.4;
    }
    &.SegmentedSelection_noPadding {
      padding: 0;
    }
  }
  .SegmentedSelection_item-content {
    display: inline-block;
    min-width: 0;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    text-align: center;
  }
  .SegmentedSelection_selected-marker {
    position: absolute;
    top: 2px;
    height: 28px;
    border-radius: 2px;
    background: var(--vWhite);
    box-shadow: 0 1px 2px 0 rgba(0 0 0 / 15%);
