@keyframes Toastify__zoomIn {
  from {
    opacity: 0;
    transform: scale3d(0.3, 0.3, 0.3);
  }
  50% {
    opacity: 1;
  }
}
@keyframes Toastify__zoomOut {
  from {
    opacity: 1;
  }
  50% {
    opacity: 0;
    transform: scale3d(0.3, 0.3, 0.3);
  }
  to {
    opacity: 0;
  }
}
.Toastify__zoom-enter {
  animation-name: Toastify__zoomIn;
}
.Toastify__zoom-exit {
  animation-name: Toastify__zoomOut;
}
@keyframes Toastify__flipIn {
  from {
    transform: perspective(400px) rotate3d(1, 0, 0, 90deg);
    animation-timing-function: ease-in;
    opacity: 0;
  }
  40% {
    transform: perspective(400px) rotate3d(1, 0, 0, -20deg);
    animation-timing-function: ease-in;
  }
  60% {
    transform: perspective(400px) rotate3d(1, 0, 0, 10deg);
    opacity: 1;
  }
  80% {
    transform: perspective(400px) rotate3d(1, 0, 0, -5deg);
  }
  to {
    transform: perspective(400px);
  }
}
@keyframes Toastify__flipOut {
  from {
    transform: perspective(400px);
  }
  30% {
    transform: perspective(400px) rotate3d(1, 0, 0, -20deg);
    opacity: 1;
  }
  to {
    transform: perspective(400px) rotate3d(1, 0, 0, 90deg);
    opacity: 0;
  }
}
.Toastify__flip-enter {
  animation-name: Toastify__flipIn;
}
.Toastify__flip-exit {
  animation-name: Toastify__flipOut;
}
@keyframes Toastify__slideInRight {
  from {
    transform: translate3d(110%, 0, 0);
    visibility: visible;
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}
@keyframes Toastify__slideInLeft {
  from {
    transform: translate3d(-110%, 0, 0);
    visibility: visible;
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}
@keyframes Toastify__slideInUp {
  from {
    transform: translate3d(0, 110%, 0);
    visibility: visible;
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}
@keyframes Toastify__slideInDown {
  from {
    transform: translate3d(0, -110%, 0);
    visibility: visible;
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}
@keyframes Toastify__slideOutRight {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    visibility: hidden;
    transform: translate3d(110%, 0, 0);
  }
}
@keyframes Toastify__slideOutLeft {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    visibility: hidden;
    transform: translate3d(-110%, 0, 0);
  }
}
@keyframes Toastify__slideOutDown {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    visibility: hidden;
    transform: translate3d(0, 500px, 0);
  }
}
@keyframes Toastify__slideOutUp {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    visibility: hidden;
    transform: translate3d(0, -500px, 0);
  }
}
.Toastify__slide-enter--top-left,
.Toastify__slide-enter--bottom-left {
  animation-name: Toastify__slideInLeft;
}
.Toastify__slide-enter--top-right,
.Toastify__slide-enter--bottom-right {
  animation-name: Toastify__slideInRight;
}
.Toastify__slide-enter--top-center {
  animation-name: Toastify__slideInDown;
}
.Toastify__slide-enter--bottom-center {
  animation-name: Toastify__slideInUp;
}
.Toastify__slide-exit--top-left,
.Toastify__slide-exit--bottom-left {
  animation-name: Toastify__slideOutLeft;
}
.Toastify__slide-exit--top-right,
.Toastify__slide-exit--bottom-right {
  animation-name: Toastify__slideOutRight;
}
.Toastify__slide-exit--top-center {
  animation-name: Toastify__slideOutUp;
}
.Toastify__slide-exit--bottom-center {
  animation-name: Toastify__slideOutDown;
}
@keyframes Toastify__spin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

/* src/components/Toast/Toast.module.css */
.Toast_toast-container {
  display: flex;
  align-items: center;
  flex-direction: column;
  width: auto;
  max-width: 640px;
  padding: 0;
}
.Toast_toast {
  border-radius: 0;
  cursor: default;
  display: flex;
  padding: 0;
  min-height: 0;
  .Toast_toast-body {
    padding: 0;
    > div > div {
      display: flex;
      align-items: center;
      .Toast_icon {
        align-items: center;
        display: flex;
        flex-direction: column;
        justify-content: center;
        min-width: 48px;
        align-self: stretch;
      }
      .Toast_text {
        display: flex;
        flex-direction: column;
        justify-content: center;
        padding: 14px 24px;
        font-family: var(--vDefaultFont);
        font-size: 14px;
        line-height: 20px;
        font-weight: 600;
        color: var(--vWhite);
        .Toast_additional-text {
          font-size: 12px;
          line-height: 16px;
          font-weight: 400;
        }
      }
      .Toast_actions {
        color: var(--vWhite);
        display: flex;
        flex-direction: row;
        justify-content: center;
        padding: 0 24px 0 0;
        * {
          color: var(--vWhite);
        }
      }
    }
  }
  &.Toast_success {
    background-color: var(--vGreen);
    .Toast_icon {
      background-color: var(--vGreenDark);
    }
  }
  &.Toast_error {
    background-color: var(--vRed);
    .Toast_icon {
      background-color: var(--vRedDark);
    }
  }
  &.Toast_pending {
    background-color: var(--vBlue);
    .Toast_icon {
      background-color: var(--vBlueDark);
    }
  }
}

/* src/components/Root/Root.module.css */
*,
*::before,
*::after {
  box-sizing: inherit;
}
html {
  box-sizing: border-box;
}
.Root_wrapper {
  display: flex;
  flex-direction: column;
  height: 100vh;
}

/* src/components/Root/components/RootContent/RootContent.module.css */
.RootContent_wrapper {
  background-color: var(--vUiHueLighter);
  overflow: auto;
  height: 100%;
  position: relative;
}

/* src/components/Layout/Layout.module.css */
.Layout_outer {
  display: flex;
  justify-content: center;
  .Layout_inner {
    margin: 0 0 -24px -32px;
    min-width: 672px;
    width: calc(100% + 32px);
    display: flex;
    flex-wrap: wrap;
    &.Layout_maxWidth-narrow {
      max-width: 672px;
    }
    &.Layout_maxWidth-medium {
      max-width: 992px;
    }
    &.Layout_maxWidth-wide {
      max-width: 1312px;
    }
    &.Layout_maxWidth-full {
      max-width: 100%;
    }
  }
  & + .Layout_outer {
    margin-top: 32px;
  }
}

/* src/components/Layout/components/LayoutColumn/LayoutColumn.module.css */
.LayoutColumn_wrapper {
  display: inline-block;
  flex-grow: 1;
  margin-left: 32px;
  margin-bottom: 24px;
  width: calc((840px - 100%) * 1000);
  max-width: 100%;
  &.LayoutColumn_dominant {
    flex-grow: 2;
  }
  &.LayoutColumn_withDivider {
    border-right: 1px solid var(--vUiHueLight);
    padding-right: 32px;
  }
}

/* src/components/ScrollableArea/ScrollableArea.module.css */
.ScrollableArea_wrapper {
  width: 100%;
  position: relative;
  .ScrollableArea_wrapper-inside {
    width: 100%;
    &.ScrollableArea_vertical {
      overflow-y: auto;
      overflow-x: hidden;
      &.ScrollableArea_small {
        max-height: 120px;
      }
      &.ScrollableArea_medium {
        max-height: 240px;
      }
      &.ScrollableArea_large {
        max-height: 480px;
      }
      &.ScrollableArea_topShadow::before {
        content: " ";
        position: absolute;
        top: 0;
        background:
          linear-gradient(
            0deg,
            rgb(238 238 238 / 0%) 0%,
            var(--vUiHue) 100%);
        height: 6px;
        width: 100%;
      }
      &.ScrollableArea_bottomShadow::after {
        content: " ";
        position: absolute;
        top: calc(100% - 6px);
        background:
          linear-gradient(
            180deg,
            rgb(238 238 238 / 0%) 0%,
            var(--vUiHue) 100%);
        height: 6px;
        width: 100%;
      }
    }
    &.ScrollableArea_horizontal {
      overflow-x: auto;
      overflow-y: hidden;
      &.ScrollableArea_leftShadow::before {
        content: " ";
        position: absolute;
        top: 0;
        left: 0;
        background:
          linear-gradient(
            270deg,
            rgb(238 238 238 / 0%) 0%,
            var(--vUiHue) 100%);
        height: 100%;
        width: 6px;
      }
      &.ScrollableArea_rightShadow::after {
        content: " ";
        position: absolute;
        top: 0;
        right: 0;
        background:
          linear-gradient(
            90deg,
            rgb(238 238 238 / 0%) 0%,
            var(--vUiHue) 100%);
        height: 100%;
        width: 6px;
      }
    }
    &::before,
    &::after {
      z-index: 1;
    }
  }
}

/* src/components/EmptyView/EmptyView.module.css */
.EmptyView_wrapper {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  width: 100%;
  height: 100%;
  background: var(--vUiHueLighter);
  .EmptyView_content {
    color: var(--vUiHueDark);
    font-size: 24px;
    font-weight: 600;
    letter-spacing: -0.11px;
  }
}

/* src/components/View/View.module.css */
.View_wrapper {
  margin: 0 auto;
  width: 100%;
  &.View_fullWidth:not(.View_overflowTopElement) > div,
  &.View_fullWidth.View_overflowTopElement .View_children-with-scroll > div {
    min-width: 640px;
    width: 100%;
    max-width: none;
  }
  &.View_fullHeight:not(.View_overflowTopElement),
  &.View_fullHeight.View_overflowTopElement .View_children-with-scroll {
    height: 100%;
    display: flex;
    flex-direction: column;
    & > div:not([class*=ViewActions_outer]):not([class*=ViewHeader_wrapper]) {
      height: 100%;
    }
  }
  &.View_heightAuto:not(.View_overflowTopElement),
  &.View_heightAuto.View_overflowTopElement .View_children-with-scroll {
    height: 100%;
    display: flex;
    flex-direction: column;
    & > div:not([class*=ViewActions_outer]):not([class*=ViewHeader_wrapper]) {
      height: auto;
      margin: 0 auto auto;
    }
  }
  &.View_overflowTopElement {
    height: 100%;
    display: flex;
    flex-direction: column;
    .View_children-with-scroll {
      height: 100%;
      overflow: auto;
    }
  }
}

/* src/components/View/components/ViewActions/ViewActions.module.css */
.ViewActions_outer {
  padding: 0 24px 24px;
  margin: 0 auto;
  width: 100%;
  min-width: 640px;
  max-width: 1280px;
  &.ViewActions_floating {
    padding: 0;
    margin: 0;
    max-width: 100%;
    border-top: 1px solid var(--vUiHue);
  }
  &.ViewActions_floating > .ViewActions_inner {
    border: 0;
    padding: 24px;
    margin: 0 auto;
    max-width: 1280px;
  }
  &.ViewActions_fullWidth {
    max-width: 100%;
    & .ViewActions_inner {
      max-width: 100%;
    }
  }
}
.ViewActions_inner {
  border-top: 1px solid var(--vUiHue);
  padding: 16px 0 32px;
}
.ViewActions_floating {
  position: sticky;
  bottom: 0;
  background-color: var(--vWhite);
  z-index: var(--vJustAboveContent);
}

/* src/components/View/components/ViewBody/ViewBody.module.css */
.ViewBody_wrapper {
  width: 100%;
  min-width: 640px;
  max-width: 1280px;
  margin: auto;
  padding: 24px;
}

/* src/components/View/components/ViewHeader/ViewHeader.module.css */
.ViewHeader_wrapper {
  width: 100%;
  min-width: 640px;
  max-width: 1280px;
  padding: 24px 24px 0;
  margin: 0 auto;
  &.ViewHeader_sticky {
    position: sticky;
    top: 0;
    width: 100%;
    max-width: none;
    border-bottom: 1px solid var(--vUiHue);
    background-color: color-mix(in srgb, var(--vWhite) 70%, transparent);
    padding-bottom: 24px;
  }
  .ViewHeader_flex {
    display: flex;
    .ViewHeader_flex-cut-text {
      flex: 1;
      min-width: 0;
    }
    .ViewHeader_flex-full-width {
      white-space: nowrap;
      margin-left: 8px;
    }
  }
  .ViewHeader_tabs {
    margin-top: 24px;
  }
  .ViewHeader_icon {
    display: inline-block;
    vertical-align: top;
    position: relative;
    top: 8px;
    margin-right: 8px;
    &.ViewHeader_onClick {
      cursor: pointer;
    }
    .ViewHeader_swapIconOnHover {
      &:hover > span:first-child {
        display: none;
      }
      &:not(:hover) > span:last-child {
        display: none;
      }
    }
  }
  .ViewHeader_inline-element {
    display: inline-block;
    vertical-align: top;
    margin-right: 8px;
  }
}
.ViewHeader_caption-wrapper {
  display: flex;
  min-height: 20px;
  .ViewHeader_copy-icon {
    visibility: hidden;
    margin-left: 4px;
    margin-top: -2px;
    margin-bottom: 2px;
  }
}
.ViewHeader_caption-wrapper:hover {
  .ViewHeader_copy-icon {
    visibility: visible;
    cursor: pointer;
  }
}
.ViewHeader_location {
  font-size: 12px;
  line-height: 20px;
  font-weight: 500;
  color: var(--vInkLighter);
}
.ViewHeader_divider {
  margin: 0 8px;
}

/* src/components/SplashScreen/SplashScreen.module.css */
.SplashScreen_wrapper {
  display: flex;
  flex-direction: column;
  justify-content: center;
  text-align: center;
  width: 100%;
  height: 100%;
  background-color: var(--vUiHueLighter);
  padding: 8px;
  [data-ppuc-id=Subtitle] {
    margin-top: 16px;
    margin-bottom: 24px;
  }
  .SplashScreen_children {
    width: 50%;
    margin: auto;
  }
}

/* src/components/WidgetContainer/WidgetContainer.module.css */
.WidgetContainer_wrapper {
  width: 100%;
  height: 100%;
  background: var(--vWhite);
  &.WidgetContainer_withBorder {
    border: 1px solid var(--vUiHue);
  }
  &.WidgetContainer_headerOnHover {
    border: 1px solid transparent;
  }
  .WidgetContainer_DashboardWidgetHandleContainer {
    padding: 8px;
    display: flex;
    align-items: center;
    cursor: grab;
    &.WidgetContainer_disabled {
      cursor: not-allowed;
    }
  }
  .WidgetContainer_widgetTopBarTitle {
    line-height: 16px;
    height: 16px;
    padding-left: 8px;
  }
  &.WidgetContainer_disabled {
    .WidgetContainer_DashboardWidgetHandle {
      cursor: none;
      padding: 26px 0;
    }
  }
  &.WidgetContainer_subdued {
    background-color: var(--vUiHueLighter);
  }
  .WidgetContainer_widgetTopBar {
    padding-right: 8px;
    &.WidgetContainer_bottomHeaderBorder {
      border-bottom: 1px solid var(--vUiHue);
    }
    &:not(.WidgetContainer_bottomHeaderBorder) {
      margin-bottom: 1px;
    }
    &.WidgetContainer_headerOnHover {
      .WidgetContainer_DashboardWidgetHandleContainer {
        visibility: hidden;
      }
      button[class*=widgetMenu] {
        display: none;
      }
    }
    .WidgetContainer_icon {
      margin-right: 8px;
    }
    .WidgetContainer_leftIcon {
      margin-left: 8px;
      .WidgetContainer_spinning-icon > * {
        animation: WidgetContainer_rotate 0.8s infinite linear;
      }
    }
  }
  .WidgetContainer_widgetTopBarHandle {
    display: inline-block;
    max-width: 100%;
    &.WidgetContainer_with-icon {
      padding-right: 8px;
    }
    :first-child::after {
      content: "\a0";
      display: inline-block;
    }
  }
  .WidgetContainer_widgetWrapper {
    overflow: hidden;
    height: calc(100% - 34px);
  }
  .WidgetContainer_subdued {
    border: 1px solid transparent;
    &:hover {
      border: 1px solid var(--vUiHue);
    }
  }
  .WidgetContainer_widgetWrapperChildren {
    &.WidgetContainer_fullHeight {
      height: 100%;
    }
    &.WidgetContainer_refreshError {
      opacity: 0.5;
    }
  }
}
div[class*=react-grid-placeholder] {
  background: var(--vBlue) !important;
  pointer-events: none;
}
.WidgetContainer_wrapper + span[class*=react-resizable-handle] {
  background-image: url(data:image/svg+xml;base64,) !important;
  &::after {
    border-right: none !important;
    border-bottom: none !important;
  }
}
div[class*=widgetMenuOpened] button[class*=widgetMenu] {
  display: flex !important;
}
div[class*=react-grid-item]:hover {
  .WidgetContainer_wrapper.WidgetContainer_headerOnHover {
    border: 1px solid var(--vUiHue);
    .WidgetContainer_widgetTopBar {
      border-bottom: 1px solid var(--vUiHue);
      margin-bottom: 0;
    }
  }
  .WidgetContainer_widgetTopBar.WidgetContainer_headerOnHover {
    .WidgetContainer_DashboardWidgetHandleContainer {
      visibility: visible;
    }
    button[class*=widgetMenu] {
      display: flex;
    }
  }
}
@keyframes WidgetContainer_rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

/* src/components/OverlayView/OverlayView.module.css */
.OverlayView_wrapper {
  width: 100%;
  height: 100%;
  position: fixed;
  .OverlayView_header {
    width: 100%;
    border-bottom: 1px solid var(--vUiHueDark);
    display: flex;
    .OverlayView_close-button-area {
      display: flex;
      justify-content: center;
      align-items: center;
    }
    &.OverlayView_variant1 {
      height: 61px;
      background-color: var(--vUiHueLight);
      border-bottom: 1px solid var(--vUiHueDark);
      .OverlayView_close-button-area {
        border-left: 1px solid var(--vUiHueDark);
        display: flex;
        justify-content: center;
        align-items: center;
        .OverlayView_close-button {
          width: 60px;
          height: 100%;
          cursor: pointer;
          display: flex;
          justify-content: center;
          align-items: center;
        }
        .OverlayView_close-button:hover {
          background-color: color-mix(in srgb, var(--vInk) 2.5%, transparent);
        }
        .OverlayView_custom-close-button-wrapper {
          padding: 0 16px;
        }
      }
    }
    &.OverlayView_variant2 {
      height: 88px;
      background-color: var(--vWhite);
      border-bottom: 1px solid var(--vUiHue);
      box-shadow: 0 1px 1px 0 rgba(0 0 0 / 6%);
      position: relative;
      z-index: 10;
      .OverlayView_close-button-area {
        border-left: 1px solid var(--vUiHue);
        padding-left: 16px;
        padding-right: 24px;
        margin: 28px 0;
      }
    }
    .OverlayView_left {
      flex-grow: 1;
      min-width: 0;
      padding-left: 24px;
      display: flex;
      align-items: center;
    }
  }
  .OverlayView_content {
    overflow: auto;
    background-color: var(--vUiHueLighter);
    &.OverlayView_variant1 {
      height: calc(100% - 61px);
    }
    &.OverlayView_variant2 {
      height: calc(100% - 88px);
    }
  }
}
.OverlayView_modal {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: var(--vOverlay);
}

/* src/components/SplitView/SplitView.module.css */
.SplitView_container {
  display: flex;
  margin: 0 auto;
  height: 100%;
  overflow: hidden;
  .SplitView_collapsed {
    display: flex;
    justify-content: center;
    align-items: center;
    min-width: 34px;
    background-color: var(--vUiHueLighter);
    border: 1px solid var(--vUiHue);
    cursor: pointer;
    height: 100%;
    z-index: var(--vContent);
    &:hover {
      background-color: var(--vUiHueLight);
    }
  }
  .SplitView_view {
    width: 100%;
    height: 100%;
    overflow: auto;
    background-color: var(--vUiHueLighter);
    &.SplitView_dotsBackground {
      background: var(--vUiHueLighter) url('data:image/svg+xml,<svg width="19" height="19" viewBox="0 0 19 19" fill="none" xmlns="http://www.w3.org/2000/svg">%0A<path d="M9.5 10.7502C10.1904 10.7502 10.75 10.1906 10.75 9.50024C10.75 8.80989 10.1904 8.25024 9.5 8.25024C8.80964 8.25024 8.25 8.80989 8.25 9.50024C8.25 10.1906 8.80964 10.7502 9.5 10.7502Z" fill="%23E1E1E1"/>%0A</svg>%0A');
    }
  }
  .SplitView_sidebar-view {
    height: 100%;
    position: relative;
    .SplitView_sidebar-collapse-icon {
      position: absolute;
      left: 100%;
      top: 50%;
      width: 16px;
      height: 16px;
      cursor: pointer;
      &:hover {
        .SplitView_collapse-icon-inactive {
          display: none;
        }
        .SplitView_collapse-icon-active {
          display: block;
        }
      }
      &.SplitView_right {
        left: -16px;
        transform: scaleX(-1);
      }
      .SplitView_collapse-icon-active {
        display: none;
      }
    }
  }
}
:root[theme=dark] .SplitView_container .SplitView_view.SplitView_dotsBackground {
  background: var(--vUiHueLighter) url('data:image/svg+xml,<svg width="19" height="19" viewBox="0 0 19 19" fill="none" xmlns="http://www.w3.org/2000/svg">%0A<path d="M9.5 10.7502C10.1904 10.7502 10.75 10.1906 10.75 9.50024C10.75 8.80989 10.1904 8.25024 9.5 8.25024C8.80964 8.25024 8.25 8.80989 8.25 9.50024C8.25 10.1906 8.80964 10.7502 9.5 10.7502Z" fill="%23292929"/>%0A</svg>%0A');
}

/* src/components/SplitView/components/Sidebar/Sidebar.module.css */
.Sidebar_wrapper {
  display: flex;
  height: 100%;
  position: relative;
  .Sidebar_fixed-width {
    max-width: 400px;
  }
  .Sidebar_resizable {
    width: 400px;
    min-width: 400px;
    max-width: 800px;
    height: 100%;
  }
  .Sidebar_resize-handler {
    position: absolute;
    height: 100%;
    width: 16px;
    top: 0;
    left: calc(100% - 8px);
    z-index: var(--vHandler);
    &.Sidebar_-active .Sidebar_resize-line {
      background-color: var(--vBlue);
    }
    &:hover {
      cursor: col-resize;
      .Sidebar_resize-line {
        background-color: var(--vBlue);
        animation: Sidebar_color_change 0.5s;
      }
    }
    .Sidebar_resize-line {
      background-color: transparent;
      width: 2px;
      height: 100%;
      margin: auto;
    }
  }
  .Sidebar_styled {
    width: 400px;
    overflow: auto;
    border-right: solid 1px var(--vUiHue);
  }
}
@keyframes Sidebar_color_change {
  0% {
    background-color: transparent;
  }
  50% {
    background-color: transparent;
  }
  100% {
    background-color: var(--vBlue);
  }
}

