body,
input,
textarea,
button,
select {
  margin: 0;
  padding: 0;
  font-family: Inter, sans-serif;
}

:focus-visible {
  outline: var(--vOutlineColor) var(--vOutlineStyle) var(--vOutlineWidth);
  outline-offset: var(--vOutlineOffset);
}

:root {
  /* colors */
  --vWhite: #fff;
  --vUiHueLighter: #fafafa;
  --vUiHueLight: #eee;
  --vUiHue: #ddd;
  --vUiHueDark: #ccc;
  --vInkLightest: #999;
