  --vBlueHover: #1075de;
  --vBlueActive: #0060c4;
  --vPurple: #6610f1;
  --vVioletLight: #f8f2ff;
  --vViolet: #8547c5;
  --vVioletDark: #662ba3;
  --vPinkLight: #ffeefe;
  --vPink: #f65cd2;
  --vPinkDark: #73195e;
  --vRedLight: #fceff1;
  --vRed: #d13a46;
  --vRedDark: #92222b;
  --vRedHover: #b9353e;
  --vOrangeLight: #ffeddb;
  --vOrange: #f57f09;
  --vOrangeDark: #ba5d00;
  --vYellowLight: #fff7d6;
  --vYellow: #ffd000;
  --vYellowDark: #bf9c00;
  --vGreenLight: #e4f9f0;
  --vGreen: #03b65e;
  --vGreenDark: #017a40;
  --vGreenHover: #029f53;
  --vTealLight: #defcfb;
  --vTeal: #00c4c1;
  --vTealDark: #008280;
  --vCyanLight: #e4fbff;
  --vCyan: #00d8ff;
  --vCyanDark: #165b77;
  --vBluebonnetLight: #f7f8ff;
  --vBluebonnet: #5760d7;
  --vBluebonnetDark: #2f39b6;
  --vAlwaysWhite: #fff;
  --vInkAlwaysDark: #131313;
  --vOutlineColor: var(--vInkLight);
  --vOutlineStyle: dashed;
  --vOutlineWidth: 1px;
  --vOutlineOffset: 1px;

  /* font styles */
  --vDefaultFont: Inter, sans-serif;
  --vInputFontSize: 14px;

  /* layers (z-index) */
  --vJustUnderContent: 99;
  --vContent: 100;
  --vJustAboveContent: 101;
  --vHandler: 1001;
  --vOverlay: 1500;
  --vPopover: 5000;
  --vModal: 5001;
  --vTooltip: 5003;

  /* shadows */
  /* stylelint-disable */
  --vPopoverShadow: 0 2px 4px 0 rgba(0, 0, 0, 0.2);
  --vRaised: 0 1px 2px 0 rgba(0, 0, 0, 0.08);
  --vHover: 0 2px 1px 0 rgba(0, 0, 0, 0.1), 0 1px 1px 0 rgba(0, 0, 0, 0.1);
  --vDragging: 0 16px 16px 0 rgba(0, 0, 0, 0.2);
  /* stylelint-enable */

  --vActionListItemHeight: 32px;
  --vListHeight: calc(var(--vActionListItemHeight) * 8);
}

